   ============================================================================= */

/* ---- Shared selection readout ---------------------------------------------
   Full-width sibling above .identity-panels. Distinct background/border
   from the (unlabeled) search inputs so it reads as a display, not an
   input. Same markup works at every viewport width — no breakpoint. */

.identity-selection {
    padding: 0.5rem 0.75rem;
    margin-bottom: 0.75rem;
    border: 1px solid #0f766e;
    border-radius: 4px;
    background: #f0faf9;
    color: #1a1a1a;
    font-size: 0.9rem;
    font-weight: 500;
}

.identity-selection-placeholder {
    color: #9ca3af;
    font-weight: 400;
    font-style: italic;
}

/* ---- Two-panel container -------------------------------------------------- */

.identity-panels {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.5rem;
    padding: 1rem 0;
    background: #f5f7fa;
}

/* ---- Individual panel ----------------------------------------------------- */

.identity-panel {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    background: #ffffff;
    border: 1px solid #dde1e7;
    border-radius: 4px;
    padding: 0.75rem;
}

/* ---- Panel search box -------------------------------------------------------
   Direct child of .identity-panel now — the header wrapper and detail
   button that used to sit next to it are gone (double-click on a row
   opens the detail panel instead). */

.identity-search {
    width: 100%;
    box-sizing: border-box;
    padding: 4px 8px;
    border: 1px solid #dde1e7;
    border-radius: 3px;
    font-size: 0.875rem;
    font-family: inherit;
    background: #ffffff;
    color: #1a1a1a;
}

.identity-search:focus {
    outline: 2px solid #0f766e;
    outline-offset: -1px;
    border-color: #0f766e;
}

/* ---- Add button ----------------------------------------------------------- */

.identity-add-btn {
    align-self: flex-start;
    padding: 3px 10px;
    border: 1px solid #0f766e;
    border-radius: 3px;
    background: none;
    color: #0f766e;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.15s;
}

.identity-add-btn:hover {
    background: #0f766e;
    color: #ffffff;
}

/* ---- Listbox -------------------------------------------------------------- */

.identity-listbox {
    border: 1px solid #dde1e7;
    border-radius: 3px;
    overflow-y: auto;
    max-height: 400px;
    background: #ffffff;
    font-size: 0.875rem;
}

/* ---- List items ------------------------------------------------------------
   Single field (name only) — detail info comes from double-click, not
   from a denser row. */

.identity-item {
    padding: 4px 8px;
    border-bottom: 1px solid #f0f0f0;
    cursor: pointer;
    line-height: 1.3;
    color: #1a1a1a;
    font-weight: 500;
}

.identity-item:last-child {
    border-bottom: none;
}

.identity-item:hover {
    background: #f0faf9;
}

.identity-item.selected {
    background: #dbeafe;
    color: #1e3a5f;
}

.identity-item.selected:hover {
    background: #bfdbfe;
}

/* ---- Empty state ---------------------------------------------------------- */

.identity-empty {
    padding: 1rem;
    color: #9ca3af;
    font-size: 0.875rem;
    text-align: center;
}

/* ---- Tab panel light background ------------------------------------------ */

.tab-panel {
    background: #f5f7fa;
}

.tab-panel .crew-content {
    background: #ffffff;
    padding: 1rem;
}

/* ---- Responsive ----------------------------------------------------------- */

@media (max-width: 768px) {
    .identity-panels {
        grid-template-columns: 1fr;
    }
}

/**
 * bidirectional-filter.js
 *
 * Reusable two-listbox cross-filter pattern: two lists of records connected
 * by a relationship (many-to-many or one-to-many). Selecting an item in
 * either list filters the other to only related items. A shared selection
 * readout shows whichever item was last clicked. Double-click opens that
 * record's detail panel; each list has its own live-search input and an
 * "add new" button.
 *
 * Not specific to any entity pair — first consumer is Organizations ↔
 * Contacts (Identities tab), but this is written generically enough for
 * any two-list cross-reference UI (e.g. a future Projects ↔ Contacts tab).
 *
 * Markup contract for each list item:
 *   <div class="identity-item"
 *        data-id="123"
 *        data-name="Display Name"
 *        data-related-ids="4,7,9">
 *
 * data-related-ids holds the comma-separated ids of items in the *other*
 * list that this item is connected to. Both sides use the same attribute
 * name — the module doesn't care which side is "left" or "right".
 *
 * Depends on: window.openDetailPanel, window.openNewRecordPanel
 * (both exposed globally by detail-panel.js).
 *
 * Usage:
 *   import { initBidirectionalFilter } from './bidirectional-filter.js';
 *
 *   initBidirectionalFilter({
 *     selectionBoxId: 'identity-selection',
 *     left: {
 *       listboxId: 'org-listbox',
 *       searchId:  'org-search',
 *       addBtnId:  'org-add-btn',
 *       entity:    'organizations',
 *     },
 *     right: {
 *       listboxId: 'contact-listbox',
 *       searchId:  'contact-search',
 *       addBtnId:  'contact-add-btn',
 *       entity:    'contacts',
 *     },
 *   });
 */

/**
 * @param {Object} config
 * @param {string} config.selectionBoxId - id of the shared selection readout element
 * @param {Object} config.left  - { listboxId, searchId, addBtnId, entity }
 * @param {Object} config.right - { listboxId, searchId, addBtnId, entity }
 */
export function initBidirectionalFilter(config) {
  const { selectionBoxId, left, right } = config;

  const selectionBox = document.getElementById(selectionBoxId);

  function makeSide(side, other) {
    return {
      listbox: document.getElementById(side.listboxId),
      search:  document.getElementById(side.searchId),
      addBtn:  document.getElementById(side.addBtnId),
      entity:  side.entity,
      selectedId: null,
      // set after both sides constructed — see wiring below
      other: null,
    };
  }

  const leftSide  = makeSide(left, right);
  const rightSide = makeSide(right, left);
  leftSide.other  = rightSide;
  rightSide.other = leftSide;

  function getItems(side) {
    return side.listbox.querySelectorAll('.identity-item');
  }

  function setItemVisible(el, visible) {
    el.style.display = visible ? '' : 'none';
  }

  function showSelection(name) {
    selectionBox.textContent = name;
    selectionBox.classList.add('has-selection');
  }

  function clearSelectionBox() {
    selectionBox.innerHTML = '<span class="identity-selection-placeholder">No selection</span>';
    selectionBox.classList.remove('has-selection');
  }

  function selectItem(side, item) {
    getItems(side).forEach(i => i.classList.remove('selected'));
    side.selectedId = item.dataset.id;
    item.classList.add('selected');
    showSelection(item.dataset.name);

    const relatedIds = item.dataset.relatedIds
      ? item.dataset.relatedIds.split(',').filter(Boolean)
      : [];
    getItems(side.other).forEach(o => {
      setItemVisible(o, relatedIds.includes(o.dataset.id));
    });

    side.other.selectedId = null;
    getItems(side.other).forEach(i => i.classList.remove('selected'));
  }

  function clearSelection(side) {
    side.selectedId = null;
    clearSelectionBox();
    getItems(side).forEach(i => {
      i.classList.remove('selected');
      setItemVisible(i, true);
    });
    applySearch(side.other);
  }

  function applySearch(side) {
    const term = side.search.value.toLowerCase();
    getItems(side).forEach(item => {
      setItemVisible(item, item.textContent.toLowerCase().includes(term));
    });
  }

  function wireSide(side) {
    side.listbox.addEventListener('click', e => {
      const item = e.target.closest('.identity-item');
      if (!item) return;
      if (item.dataset.id === side.selectedId) {
        clearSelection(side);
      } else {
        selectItem(side, item);
      }
    });

    side.listbox.addEventListener('dblclick', e => {
      const item = e.target.closest('.identity-item');
      if (!item) return;
      window.openDetailPanel(side.entity, item.dataset.id);
    });

    side.search.addEventListener('input', () => {
      if (side.selectedId) clearSelection(side);
      applySearch(side);
    });

    if (side.addBtn) {
      side.addBtn.addEventListener('click', () => {
        window.openNewRecordPanel(side.entity);
      });
    }
  }

  wireSide(leftSide);
  wireSide(rightSide);
}

# Changedoc: Identities tab redesign — shared selection box, single-field rows, dblclick-to-detail

**Files:** `templates/partials/_tab_identities.html`, `static/css/identity.css`
**Type:** UI/UX restructure — layout, markup, and JS wiring. No backend changes
(those are covered separately in the crew.py contacts/organizations routes
changedoc).

**Reason:** Mobile-first redesign of the Captain's Identities tab.
- `⋯` detail buttons are redundant now that double-click opens the detail
  form directly (mirrors the `⋯` behavior on projects datasheet rows) —
  removed.
- Listbox rows drop the email hint line — name only, per decision that
  detail comes from double-click, not from a denser row.
- A single full-width "current selection" readout replaces the previous
  pattern of writing the selected name into the search `<input>` — fixes
  both the truncation problem (long names) and the confusing overload of
  the search box doubling as a selection display.
- `+ Contact` / `+ Organization` buttons wired to `openNewRecordPanel()`
  (already exists in `detail-panel.js`, entity-agnostic, no JS changes
  needed there).
- Columns stay 50/50 side-by-side at all widths — no stacking breakpoint —
  since the selection box already solves the "can't see the full name"
  problem the two-column width was creating.

