/**
 * detail-panel.js
 *
 * Handles detail panel interactions:
 * - Opening detail panel for existing records (⋯ button)
 * - Opening detail panel for new records (+ Add button)
 * - Closing panel on × / Alt+X / Escape
 * - Tab switching
 * - Save (Alt+S) — save and close
 * - New  (Alt+N) — save current, clear form, focus Name
 * - Discard (Alt+X) — discard and close
 *
 * Hero image and detail panel occupy the same spot. Opening the panel
 * hides the hero (display:none) and shows the panel (display:flex).
 */

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

function getPanel() {
  return document.querySelector('#detail-panel-container .detail-panel');
}

function getForm() {
  return document.getElementById('detail-form');
}

function getHero() {
  return document.querySelector('.crew-header');
}

function showPanel() {
  const panel = getPanel();
  const hero  = getHero();
  if (panel) panel.classList.add('active');
  if (hero)  hero.classList.add('hidden');
}

function hidePanel() {
  const panel = getPanel();
  const hero  = getHero();
  if (panel) panel.classList.remove('active');
  if (hero)  hero.classList.remove('hidden');
}

function resetToDetailsTab() {
  const panel = getPanel();
  if (!panel) return;
  panel.querySelectorAll('.detail-tab-button').forEach(b => b.classList.remove('active'));
  panel.querySelectorAll('.detail-tab-panel').forEach(p => p.classList.remove('active'));
  const firstBtn   = panel.querySelector('.detail-tab-button');
  const detailsTab = panel.querySelector('.detail-tab-panel[data-tab="details"]');
  if (firstBtn)   firstBtn.classList.add('active');
  if (detailsTab) detailsTab.classList.add('active');
}

function clearForm() {
  const form = getForm();
  if (!form) return;
  form.dataset.id = '';
  form.querySelectorAll('input, textarea').forEach(el => el.value = '');
  form.querySelectorAll('select').forEach(el => el.selectedIndex = 0);
}

function focusName() {
  const nameField = document.getElementById('detail-name');
  if (nameField) {
    nameField.focus();
    nameField.select();
  }
}

function populateForm(record) {
  const form = getForm();
  if (!form) return;
  form.dataset.id = record.id ?? '';

  const nameField   = form.querySelector('[name="name"]');
  const typeField   = form.querySelector('[name="type_id"]');
  const statusField = form.querySelector('[name="status_id"]');
  const descField   = form.querySelector('[name="description"]');

  if (nameField)   nameField.value   = record.name        ?? '';
  if (typeField)   typeField.value   = record.type_id     ?? '';
  if (statusField) statusField.value = record.status_id   ?? '';
  if (descField)   descField.value   = record.description ?? '';
}

// ---------------------------------------------------------------------------
// Save to server
// Returns the saved record on success, null on failure.
// ---------------------------------------------------------------------------

// Guard against double-saves from rapid clicks or accesskey + click firing together
let _saving = false;

async function saveForm() {
  const form = getForm();
  if (!form) return null;

  const entity   = form.dataset.entity;
  const recordId = form.dataset.id;
  const isNew    = !recordId;

  const formData = new FormData(form);
  const data     = Object.fromEntries(formData);

  const url = isNew
    ? `/crew/${entity}/save`
    : `/crew/${entity}/${recordId}/save`;

  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });

    if (res.ok) {
      const saved = await res.json();
      // Update form id to the newly saved record's id
      form.dataset.id = saved.id;
      const panel = getPanel();
      if (panel) panel.dataset.id = saved.id;
      return saved;
    } else {
      // crew.py returns {"success": false, "message": "..."} on proc
      // rejection (duplicate name, not found, etc.) — read message, not
      // detail, or this always falls back to the generic string below.
      const err = await res.json().catch(() => ({ message: res.statusText }));
      alert(err.message || 'Save failed');
      return null;
    }
  } catch (err) {
    console.error('Save error:', err);
    alert('Save error: ' + err.message);
    return null;
  }
}

// ---------------------------------------------------------------------------
// Button handlers
// ---------------------------------------------------------------------------

async function handleSave() {
  if (_saving) return;
  _saving = true;
  try {
    const saved = await saveForm();
    if (saved) {
      if (window._refreshProjectsGrid) window._refreshProjectsGrid();
      hidePanel();
    }
  } finally {
    _saving = false;
  }
}

async function handleNew() {
  if (_saving) return;
  _saving = true;
  try {
    const saved = await saveForm();
    if (!saved) return;
    clearForm();
    resetToDetailsTab();
    focusName();
    if (window._refreshProjectsGrid) window._refreshProjectsGrid();
  } finally {
    _saving = false;
  }
}

function handleDiscard() {
  hidePanel();
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Open detail panel for an existing record.
 * Fetches record from server and populates the form.
 */
export async function openDetailPanel(entity, recordId) {
  let record;
  try {
    const res = await fetch(`/crew/${entity}/${recordId}`);
    if (!res.ok) throw new Error(`Fetch failed: ${res.status}`);
    record = await res.json();
  } catch (err) {
    console.error('Could not fetch record:', err);
    return;
  }

  const panel = getPanel();
  const form  = getForm();
  if (!panel || !form) return;

  panel.dataset.entity = entity;
  panel.dataset.id     = recordId;
  form.dataset.entity  = entity;

  populateForm(record);
  resetToDetailsTab();
  showPanel();
}

/**
 * Open detail panel in new-record mode.
 * Form is empty, save will POST to /crew/{entity}/save.
 */
export function openNewRecordPanel(entity) {
  const panel = getPanel();
  const form  = getForm();
  if (!panel || !form) return;

  panel.dataset.entity = entity;
  panel.dataset.id     = '';
  form.dataset.entity  = entity;

  clearForm();
  resetToDetailsTab();
  showPanel();
  focusName();
}

/**
 * Close the detail panel and restore the hero image.
 */
export function closeDetailPanel() {
  hidePanel();
}

// ---------------------------------------------------------------------------
// Init — wire up all event listeners
// ---------------------------------------------------------------------------

export function initDetailPanel() {
  // Tab switching
  document.addEventListener('click', (e) => {
    if (e.target.classList.contains('detail-tab-button')) {
      const panel = e.target.closest('.detail-panel');
      if (!panel) return;
      const targetTab = e.target.dataset.tab;
      panel.querySelectorAll('.detail-tab-button').forEach(b => b.classList.remove('active'));
      panel.querySelectorAll('.detail-tab-panel').forEach(p => p.classList.remove('active'));
      e.target.classList.add('active');
      const tabPanel = panel.querySelector(`.detail-tab-panel[data-tab="${targetTab}"]`);
      if (tabPanel) tabPanel.classList.add('active');
    }

    if (e.target.classList.contains('detail-close-button')) handleDiscard();

    // btn-save is type="submit" with form="detail-form" (see forms.yaml) so
    // clicking it also triggers native form submission. Without preventDefault
    // here, the browser's native GET-to-current-URL submission races the
    // fetch() in handleSave() and wins, since nothing else stops it.
    if (e.target.classList.contains('btn-save')) {
      e.preventDefault();
      handleSave();
    }
    if (e.target.classList.contains('btn-new'))             handleNew();
    if (e.target.classList.contains('btn-discard'))         handleDiscard();
  });

  // Keyboard shortcuts
  document.addEventListener('keydown', (e) => {
    const panel = getPanel();
    if (!panel?.classList.contains('active')) return;

    // Alt+S — Save and close
    if (e.altKey && e.key === 's') { e.preventDefault(); handleSave(); }
    // Alt+N — Save and new
    if (e.altKey && e.key === 'n') { e.preventDefault(); handleNew(); }
    // Alt+X or Escape — Discard and close
    if ((e.altKey && e.key === 'x') || e.key === 'Escape') { e.preventDefault(); handleDiscard(); }
  });

  // Safety net: catch any native form submission (e.g. pressing Enter in a
  // text input, which submits the nearest form by default browser behavior)
  // that isn't already intercepted by the btn-save click handler above.
  // Without this, Enter-to-submit falls back to a GET on the current URL
  // with form fields as query params, identical to the btn-save race bug.
  document.addEventListener('submit', (e) => {
    if (e.target.id === 'detail-form') {
      e.preventDefault();
      handleSave();
    }
  });
}

// ---------------------------------------------------------------------------
// Expose for non-module scripts (e.g. _projects_table.html)
// ---------------------------------------------------------------------------
window.openDetailPanel    = openDetailPanel;
window.openNewRecordPanel = openNewRecordPanel;
window.closeDetailPanel   = closeDetailPanel;

// Initialize
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initDetailPanel);
} else {
  initDetailPanel();
}

# Changedoc: detail-panel.js — Fix Save button racing native form submission

**File:** `static/js/detail-panel.js`
**Date:** 2026-06-29
**Source verified:** Uploaded directly by Carolyn.

## Root cause

`forms.yaml` defines the Save button as:

```yaml
save:
  type: submit
  form_id: detail-form
```

Rendered to HTML, that's `<button type="submit" form="detail-form">`. A
`type="submit"` button explicitly associated with a form via the `form`
attribute does two things on click, simultaneously: (1) it's a normal DOM
element, so any click-delegation listener on it fires normally, and (2) it
triggers the browser's **native form submission** for `#detail-form`,
independent of any JS.

`initDetailPanel()`'s click listener does call `handleSave()` when
`btn-save` is clicked — that part works. But nothing ever calls
`e.preventDefault()` on that click, and `#detail-form` has no `submit`
listener either. So native submission fires unopposed, racing the
`fetch()`-based `handleSave()`. Since `#detail-form` has no `action` or
`method` attribute, native submission falls back to browser default: **GET
to the current page URL**, with every form field serialized as a query
string parameter.

That's the exact symptom observed: clicking Save produced
`GET /crew?name=API+TEST&type_id=1&status_id=1&description=test` in the
server log instead of `POST /crew/projects/save` with a JSON body.
`crew_dashboard` doesn't read those query params for anything, so the page
just silently re-renders with no save having occurred — no error, no
console output, nothing — which is exactly why this was hard to spot from
symptoms alone.

A second, not-yet-triggered instance of the same root cause: with no
`keydown`-based Enter-key interception in this version of the file (an
earlier version of `detail-panel.js` reviewed earlier in this project had
Enter-to-next-field navigation; this one doesn't), pressing Enter inside any
text input in `#detail-form` also triggers native form submission by
default browser behavior — same GET-to-current-URL fallback, different
trigger.

## Fix

Two changes, both inside `initDetailPanel()`:

1. **Guard the `btn-save` click branch** with `e.preventDefault()` before
   calling `handleSave()`.
2. **Add a `submit` listener on `document`**, scoped to `#detail-form`,
   that calls `e.preventDefault()` and `handleSave()`. This is the more
   robust fix — it catches *any* path to native submission (Enter key,
   future buttons, accessibility tools that trigger submit programmatically)
   rather than only the one button click. The click-handler guard stays in
   as well; it's redundant once the submit listener exists, but costs
   nothing and documents intent at the point of the click.

`btn-new` and `btn-discard` are `type: button` in `forms.yaml` (not
`submit`), so they were never part of this bug and needed no changes.

---

## Change 1 — Guard the Save click handler

### BEFORE

```javascript
    if (e.target.classList.contains('detail-close-button')) handleDiscard();
    if (e.target.classList.contains('btn-save'))            handleSave();
    if (e.target.classList.contains('btn-new'))             handleNew();
    if (e.target.classList.contains('btn-discard'))         handleDiscard();
```

### AFTER

```javascript
    if (e.target.classList.contains('detail-close-button')) handleDiscard();

    // btn-save is type="submit" with form="detail-form" (see forms.yaml) so
    // clicking it also triggers native form submission. Without preventDefault
    // here, the browser's native GET-to-current-URL submission races the
    // fetch() in handleSave() and wins, since nothing else stops it.
    if (e.target.classList.contains('btn-save')) {
      e.preventDefault();
      handleSave();
    }
    if (e.target.classList.contains('btn-new'))             handleNew();
    if (e.target.classList.contains('btn-discard'))         handleDiscard();
```

### Why

Stops the click itself from triggering native submission. On its own this
would have fixed the observed bug (clicking Save), but not the Enter-key
path, hence Change 2.

---

## Change 2 — Add a submit listener as the primary fix

### BEFORE

*(no submit listener exists anywhere in the file — confirmed via
`getEventListeners(document).submit` returning `undefined` in DevTools)*

```javascript
  // Keyboard shortcuts
  document.addEventListener('keydown', (e) => {
    const panel = getPanel();
    if (!panel?.classList.contains('active')) return;

    // Alt+S — Save and close
    if (e.altKey && e.key === 's') { e.preventDefault(); handleSave(); }
    // Alt+N — Save and new
    if (e.altKey && e.key === 'n') { e.preventDefault(); handleNew(); }
    // Alt+X or Escape — Discard and close
    if ((e.altKey && e.key === 'x') || e.key === 'Escape') { e.preventDefault(); handleDiscard(); }
  });
```

### AFTER

```javascript
  // Keyboard shortcuts
  document.addEventListener('keydown', (e) => {
    const panel = getPanel();
    if (!panel?.classList.contains('active')) return;

    // Alt+S — Save and close
    if (e.altKey && e.key === 's') { e.preventDefault(); handleSave(); }
    // Alt+N — Save and new
    if (e.altKey && e.key === 'n') { e.preventDefault(); handleNew(); }
    // Alt+X or Escape — Discard and close
    if ((e.altKey && e.key === 'x') || e.key === 'Escape') { e.preventDefault(); handleDiscard(); }
  });

  // Safety net: catch any native form submission (e.g. pressing Enter in a
  // text input, which submits the nearest form by default browser behavior)
  // that isn't already intercepted by the btn-save click handler above.
  // Without this, Enter-to-submit falls back to a GET on the current URL
  // with form fields as query params, identical to the btn-save race bug.
  document.addEventListener('submit', (e) => {
    if (e.target.id === 'detail-form') {
      e.preventDefault();
      handleSave();
    }
  });
```

### Why

This is the architecturally correct fix — intercepting at the `submit`
event level catches every path to native submission, not just one button.
Scoped to `e.target.id === 'detail-form'` so it doesn't interfere with any
other form that might exist on the page (e.g. a future contacts or tasks
form using a different id, or the login form on a different page — though
this script only loads where `#detail-panel-container` exists).

---

## Change 3 — Read `err.message` instead of `err.detail`

### BEFORE

```javascript
    } else {
      const err = await res.json().catch(() => ({ detail: res.statusText }));
      alert(err.detail || 'Save failed');
      return null;
    }
```

### AFTER

```javascript
    } else {
      // crew.py returns {"success": false, "message": "..."} on proc
      // rejection (duplicate name, not found, etc.) — read message, not
      // detail, or this always falls back to the generic string below.
      const err = await res.json().catch(() => ({ message: res.statusText }));
      alert(err.message || 'Save failed');
      return null;
    }
```

### Why

`crew.py`'s save/delete routes (prior session) return
`{"success": false, "message": "..."}` on proc-rejected saves — there is no
`detail` key. As originally written, `err.detail` would always be
`undefined`, so every proc rejection (duplicate name, not found, etc.)
surfaced as the generic `'Save failed'` fallback instead of the proc's
actual human-readable message. This directly satisfies the "Felipe should
see what went wrong without checking logs" requirement from the prior
session — now the real message reaches the alert.

Note: the `err.message` read inside the JS-level `catch` block further down
(network/parse failures, a standard JS `Error` object) is unrelated and was
already correct — only the proc-rejection branch needed this change.

## Verification steps

1. Reload `/crew?role=captain`.
2. Open DevTools Console, run `getEventListeners(document).submit` — should
   now show one listener (was `undefined` before this fix).
3. Click "+ Add Project", fill in Name/Type/Status, click Save.
4. **Confirm in the Network tab:** request should be
   `POST /crew/projects/save` with `Content-Type: application/json`, not a
   GET with query params on `/crew`.
5. **Confirm the URL bar does not change** — no `?name=...&type_id=...`
   appended to `/crew`.
6. Repeat using Enter key instead of clicking Save (focus a field, press
   Enter) — same expected behavior as step 4–5.
7. Confirm the new project appears in the grid and the panel closes
   (`handleSave()` calls `hidePanel()` on success).
8. Test a duplicate name to confirm the `{success: false, message}` path
   from the `crew.py` proc-call changes surfaces via the `alert()` in
   `saveForm()`'s failure branch — this was already wired correctly in this
   file (`alert(err.detail || 'Save failed')`), but it's worth confirming
   end-to-end now that both halves (backend proc call, frontend form
   submission) are fixed.

## Note on payload key mismatch (now fixed — see Change 3 above)

`saveForm()`'s failure branch originally read `err.detail`, but `crew.py`
returns `{"success": false, "message": "..."}` — no `detail` key. This was
caught while drafting this changedoc and fixed in the same pass (Change 3)
rather than left as a follow-up, since it was a one-line read with no open
design decision: `crew.py`'s response contract was already settled last
session.

-- =============================================================================
-- 06_api.sql — API schema: stored procedures and web_app_user role
-- =============================================================================
--
-- This schema is the ONLY interface between the application and raw data.
-- Python routes call procs here; they never touch identity.* or projects.*
-- tables directly.
--
-- Security model:
--   web_app_user  — application DB role; EXECUTE on api.* only
--   steward       — existing dev/admin role; retained for direct table access
--                   during development; revoke when going public
--   All procs use SECURITY DEFINER so they run as the proc owner (postgres),
--   not as web_app_user. web_app_user cannot read tables directly.
--
-- Auth flow:
--   1. Python receives username + password from login form
--   2. Python calls api.login(username, password)
--   3. Proc fetches hash, verifies with pgcrypto crypt(), creates session
--   4. Proc returns JSONB: {success, session_token, user_id, role, crew_role}
--   5. Python sets signed cookie containing session_token
--   6. Every request: Python calls api.validate_session(token)
--   7. Logout: Python calls api.invalidate_session(token)
--
-- Uniform response envelope:
--   Success: {"success": true,  "data": {...}, "message": "..."}
--   Failure: {"success": false, "data": null,  "message": "Human-readable error"}
--
-- Depends on: 01_audit.sql, 02_identity.sql, 03_projects.sql, pgcrypto extension
-- =============================================================================

CREATE SCHEMA IF NOT EXISTS api;


-- =============================================================================
-- web_app_user role
-- The application connects to PostgreSQL as this role in production.
-- Cannot SELECT, INSERT, UPDATE, or DELETE any table directly.
-- Can only EXECUTE functions in the api schema.
-- =============================================================================

DO $$
BEGIN
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'web_app_user') THEN
        CREATE ROLE web_app_user WITH LOGIN PASSWORD 'change_me_before_production';
    END IF;
END
$$;

-- web_app_user gets schema visibility but no table access
GRANT USAGE ON SCHEMA api TO web_app_user;

-- Explicitly deny direct table access (belt and suspenders)
-- web_app_user has no GRANT on identity.* or projects.* so this is
-- already the default — stated here for documentation clarity.


-- =============================================================================
-- api.create_session(user_id, remember_me)
--
-- Internal helper — called by api.login(), also available standalone
-- for future SSO or token refresh flows.
--
-- Generates a 32-byte (64 hex char) cryptographically random session token.
-- remember_me = TRUE  → expires in 30 days
-- remember_me = FALSE → expires in 8 hours
--
-- Returns the session token as TEXT.
-- =============================================================================

CREATE OR REPLACE FUNCTION api.create_session(
    p_user_id    BIGINT,
    p_remember   BOOLEAN  DEFAULT FALSE,
    p_ip         VARCHAR  DEFAULT NULL,
    p_user_agent VARCHAR  DEFAULT NULL
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_token      VARCHAR(128);
    v_expires_at TIMESTAMPTZ;
BEGIN
    -- Generate cryptographically random token (32 bytes = 64 hex chars)
    v_token := encode(gen_random_bytes(32), 'hex');

    -- Set expiry based on remember_me flag
    v_expires_at := CASE
        WHEN p_remember THEN NOW() + INTERVAL '30 days'
        ELSE                  NOW() + INTERVAL '8 hours'
    END;

    INSERT INTO identity.app_user_sessions (
        user_id,
        session_token,
        expires_at,
        ip_address,
        user_agent
    ) VALUES (
        p_user_id,
        v_token,
        v_expires_at,
        p_ip,
        p_user_agent
    );

    RETURN v_token;
END;
$$;


-- =============================================================================
-- api.login(username, password, remember_me, ip, user_agent)
--
-- Verifies credentials using pgcrypto bcrypt.
-- On success: creates a session, updates last_login, returns full user context.
-- On failure: returns success=false with a safe error message.
--
-- The password hash never leaves the database.
-- Python receives only the session token and user metadata.
--
-- Response JSONB shape (success):
-- {
--   "success": true,
--   "message": "Login successful.",
--   "data": {
--     "session_token": "...",
--     "user_id": 1,
--     "username": "carolyn",
--     "user_role": "admin",
--     "crew_role": "captain",   -- null for customer portal users
--     "contact_id": 1
--   }
-- }
-- =============================================================================

CREATE OR REPLACE FUNCTION api.login(
    p_username   VARCHAR,
    p_password   VARCHAR,
    p_remember   BOOLEAN  DEFAULT FALSE,
    p_ip         VARCHAR  DEFAULT NULL,
    p_user_agent VARCHAR  DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user        identity.app_user%ROWTYPE;
    v_user_role   VARCHAR(50);
    v_crew_role   VARCHAR(50);
    v_token       TEXT;
BEGIN
    -- Fetch user record by username
    SELECT * INTO v_user
    FROM identity.app_user
    WHERE username = p_username;

    -- User not found — same message as wrong password (no enumeration)
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'data',    NULL,
            'message', 'Invalid username or password.'
        );
    END IF;

    -- Account inactive
    IF NOT v_user.is_active THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'data',    NULL,
            'message', 'Account is inactive. Contact your administrator.'
        );
    END IF;

    -- Verify password using pgcrypto bcrypt
    -- crypt() with the stored hash as salt re-hashes the input and compares
    IF v_user.password_hash != crypt(p_password, v_user.password_hash) THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'data',    NULL,
            'message', 'Invalid username or password.'
        );
    END IF;

    -- Fetch role names for response
    SELECT name INTO v_user_role
    FROM identity.user_role
    WHERE id = v_user.role_id;

    SELECT name INTO v_crew_role
    FROM identity.crew_role
    WHERE id = v_user.crew_role_id;
    -- v_crew_role will be NULL for customer portal users — that's correct

    -- Create session
    v_token := api.create_session(v_user.id, p_remember, p_ip, p_user_agent);

    -- Update last_login timestamp
    UPDATE identity.app_user
    SET last_login = NOW()
    WHERE id = v_user.id;

    -- Return success envelope
    RETURN jsonb_build_object(
        'success', TRUE,
        'message', 'Login successful.',
        'data', jsonb_build_object(
            'session_token', v_token,
            'user_id',       v_user.id,
            'username',      v_user.username,
            'user_role',     v_user_role,
            'crew_role',     v_crew_role,
            'contact_id',    v_user.contact_id
        )
    );

EXCEPTION WHEN OTHERS THEN
    -- Never leak internal error details to the caller
    RAISE WARNING 'api.login error for user %: %', p_username, SQLERRM;
    RETURN jsonb_build_object(
        'success', FALSE,
        'data',    NULL,
        'message', 'An unexpected error occurred. Please try again.'
    );
END;
$$;


-- =============================================================================
-- api.validate_session(token, ip)
--
-- Called by Python middleware on every authenticated request.
-- Returns full user context if session is valid and not expired.
-- Returns null data if session is missing, expired, or invalid.
-- Updates last_seen_at as a sliding window.
--
-- Python middleware pattern:
--   result = await db.fetch_one("SELECT api.validate_session(%s)", (token,))
--   if not result["success"]: redirect to login
--   request.state.user = result["data"]
-- =============================================================================

CREATE OR REPLACE FUNCTION api.validate_session(
    p_token VARCHAR,
    p_ip    VARCHAR DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_session identity.app_user_sessions%ROWTYPE;
    v_user    identity.app_user%ROWTYPE;
    v_user_role  VARCHAR(50);
    v_crew_role  VARCHAR(50);
BEGIN
    -- Fetch session
    SELECT * INTO v_session
    FROM identity.app_user_sessions
    WHERE session_token = p_token;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'data',    NULL,
            'message', 'Session not found.'
        );
    END IF;

    -- Check expiry
    IF v_session.expires_at < NOW() THEN
        -- Clean up expired session
        DELETE FROM identity.app_user_sessions WHERE id = v_session.id;
        RETURN jsonb_build_object(
            'success', FALSE,
            'data',    NULL,
            'message', 'Session expired.'
        );
    END IF;

    -- Fetch user
    SELECT * INTO v_user
    FROM identity.app_user
    WHERE id = v_session.user_id AND is_active = TRUE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'data',    NULL,
            'message', 'User not found or inactive.'
        );
    END IF;

    -- Fetch role names
    SELECT name INTO v_user_role FROM identity.user_role  WHERE id = v_user.role_id;
    SELECT name INTO v_crew_role FROM identity.crew_role  WHERE id = v_user.crew_role_id;

    -- Slide the window — update last_seen_at
    UPDATE identity.app_user_sessions
    SET last_seen_at = NOW()
    WHERE id = v_session.id;

    RETURN jsonb_build_object(
        'success', TRUE,
        'message', 'Session valid.',
        'data', jsonb_build_object(
            'user_id',    v_user.id,
            'username',   v_user.username,
            'user_role',  v_user_role,
            'crew_role',  v_crew_role,
            'contact_id', v_user.contact_id,
            'session_id', v_session.id
        )
    );

EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'api.validate_session error: %', SQLERRM;
    RETURN jsonb_build_object(
        'success', FALSE,
        'data',    NULL,
        'message', 'Session validation error.'
    );
END;
$$;


-- =============================================================================
-- api.invalidate_session(token)
--
-- Logout. Deletes the session row — instant revocation.
-- Always returns success=true (idempotent — logging out twice is not an error).
-- =============================================================================

CREATE OR REPLACE FUNCTION api.invalidate_session(
    p_token VARCHAR
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    DELETE FROM identity.app_user_sessions
    WHERE session_token = p_token;

    RETURN jsonb_build_object(
        'success', TRUE,
        'data',    NULL,
        'message', 'Logged out.'
    );

EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'api.invalidate_session error: %', SQLERRM;
    RETURN jsonb_build_object(
        'success', FALSE,
        'data',    NULL,
        'message', 'Logout error.'
    );
END;
$$;


-- =============================================================================
-- api.purge_expired_sessions()
--
-- Housekeeping proc — deletes all expired session rows.
-- Call this on a schedule (e.g. pg_cron nightly, or from a Python startup hook).
-- Returns count of deleted rows in message.
-- =============================================================================

CREATE OR REPLACE FUNCTION api.purge_expired_sessions()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_count INT;
BEGIN
    DELETE FROM identity.app_user_sessions
    WHERE expires_at < NOW();

    GET DIAGNOSTICS v_count = ROW_COUNT;

    RETURN jsonb_build_object(
        'success', TRUE,
        'data',    jsonb_build_object('deleted_count', v_count),
        'message', format('Purged %s expired session(s).', v_count)
    );

EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'api.purge_expired_sessions error: %', SQLERRM;
    RETURN jsonb_build_object(
        'success', FALSE,
        'data',    NULL,
        'message', 'Purge error.'
    );
END;
$$;


-- =============================================================================
-- api.save_project(payload JSONB, user_id BIGINT)
--
-- Insert or update a project record.
-- payload.id present and non-null → UPDATE; absent or null → INSERT.
--
-- Handles:
--   - Slug generation from name (lowercase, spaces to hyphens, deduplication)
--   - status_id and type_id lookup by name if provided as strings
--   - created_by / updated_by stamping
--   - Conflict detection (duplicate name)
--
-- Payload shape:
-- {
--   "id":          null,           -- null/absent = INSERT, int = UPDATE
--   "name":        "My Project",   -- required
--   "description": "...",          -- optional
--   "notes":       "...",          -- optional
--   "status":      "active",       -- name string, looked up to id
--   "type":        "coding",       -- name string, looked up to id (nullable)
--   "target_date": "2026-12-31"    -- ISO date string (nullable)
-- }
-- =============================================================================

CREATE OR REPLACE FUNCTION api.save_project(
    p_payload JSONB,
    p_user_id BIGINT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_id          BIGINT;
    v_name        VARCHAR(255);
    v_slug        VARCHAR(100);
    v_slug_base   VARCHAR(100);
    v_slug_suffix INT := 0;
    v_description TEXT;
    v_notes       TEXT;
    v_status_id   BIGINT;
    v_type_id     BIGINT;
    v_target_date DATE;
    v_is_update   BOOLEAN;
BEGIN
    -- Extract and validate required fields
    v_name := TRIM(p_payload->>'name');

    IF v_name IS NULL OR v_name = '' THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'data',    NULL,
            'message', 'Project name is required.'
        );
    END IF;

    -- Determine insert vs update
    v_id        := (p_payload->>'id')::BIGINT;
    v_is_update := v_id IS NOT NULL;

    -- Optional fields
    v_description := NULLIF(TRIM(p_payload->>'description'), '');
    v_notes       := NULLIF(TRIM(p_payload->>'notes'), '');
    v_target_date := NULLIF(p_payload->>'target_date', '')::DATE;

    -- Resolve status by name (required)
    SELECT id INTO v_status_id
    FROM projects.project_status
    WHERE name = LOWER(TRIM(p_payload->>'status'));

    IF v_status_id IS NULL THEN
        -- Default to 'active' if not provided or not found
        SELECT id INTO v_status_id
        FROM projects.project_status
        WHERE name = 'active';
    END IF;

    -- Resolve type by name (optional)
    IF p_payload->>'type' IS NOT NULL AND p_payload->>'type' != '' THEN
        SELECT id INTO v_type_id
        FROM projects.project_type
        WHERE name = LOWER(TRIM(p_payload->>'type'));
    END IF;

    IF v_is_update THEN
        -- Verify record exists
        IF NOT EXISTS (SELECT 1 FROM projects.projects WHERE id = v_id) THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'data',    NULL,
                'message', 'Project not found.'
            );
        END IF;

        -- Check for name conflict on other records
        IF EXISTS (
            SELECT 1 FROM projects.projects
            WHERE name = v_name AND id != v_id
        ) THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'data',    NULL,
                'message', 'A project with that name already exists.'
            );
        END IF;

        UPDATE projects.projects SET
            name        = v_name,
            description = v_description,
            notes       = v_notes,
            status_id   = v_status_id,
            type_id     = v_type_id,
            target_date = v_target_date,
            updated_by  = p_user_id
        WHERE id = v_id;

        RETURN jsonb_build_object(
            'success', TRUE,
            'data',    jsonb_build_object('id', v_id),
            'message', 'Project updated.'
        );

    ELSE
        -- INSERT path

        -- Check for name conflict
        IF EXISTS (SELECT 1 FROM projects.projects WHERE name = v_name) THEN
            RETURN jsonb_build_object(
                'success', FALSE,
                'data',    NULL,
                'message', 'A project with that name already exists.'
            );
        END IF;

        -- Generate slug from name
        -- lowercase, replace non-alphanumeric with hyphens, collapse multiples
        v_slug_base := LOWER(REGEXP_REPLACE(
            REGEXP_REPLACE(v_name, '[^a-zA-Z0-9\s-]', '', 'g'),
            '\s+', '-', 'g'
        ));
        v_slug_base := TRIM(BOTH '-' FROM v_slug_base);
        v_slug      := v_slug_base;

        -- Deduplicate slug if needed
        WHILE EXISTS (SELECT 1 FROM projects.projects WHERE slug = v_slug) LOOP
            v_slug_suffix := v_slug_suffix + 1;
            v_slug := v_slug_base || '-' || v_slug_suffix;
        END LOOP;

        INSERT INTO projects.projects (
            name, slug, description, notes,
            status_id, type_id, target_date,
            created_by, updated_by
        ) VALUES (
            v_name, v_slug, v_description, v_notes,
            v_status_id, v_type_id, v_target_date,
            p_user_id, p_user_id
        )
        RETURNING id INTO v_id;

        RETURN jsonb_build_object(
            'success', TRUE,
            'data',    jsonb_build_object('id', v_id, 'slug', v_slug),
            'message', 'Project created.'
        );
    END IF;

EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'api.save_project error: %', SQLERRM;
    RETURN jsonb_build_object(
        'success', FALSE,
        'data',    NULL,
        'message', 'An unexpected error occurred saving the project.'
    );
END;
$$;


-- =============================================================================
-- api.delete_project(id BIGINT, user_id BIGINT)
--
-- Soft-deletes are not implemented yet — this is a hard delete.
-- Audit trigger on projects.projects captures the DELETE for the log.
-- Returns error if project has dependent records that block deletion.
-- =============================================================================

CREATE OR REPLACE FUNCTION api.delete_project(
    p_id      BIGINT,
    p_user_id BIGINT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM projects.projects WHERE id = p_id) THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'data',    NULL,
            'message', 'Project not found.'
        );
    END IF;

    DELETE FROM projects.projects WHERE id = p_id;

    RETURN jsonb_build_object(
        'success', TRUE,
        'data',    jsonb_build_object('id', p_id),
        'message', 'Project deleted.'
    );

EXCEPTION WHEN foreign_key_violation THEN
    RETURN jsonb_build_object(
        'success', FALSE,
        'data',    NULL,
        'message', 'Cannot delete project — it has dependent records.'
    );
WHEN OTHERS THEN
    RAISE WARNING 'api.delete_project error for id %: %', p_id, SQLERRM;
    RETURN jsonb_build_object(
        'success', FALSE,
        'data',    NULL,
        'message', 'An unexpected error occurred deleting the project.'
    );
END;
$$;


