/* =============================================================================
   Detail Panel Component

   Fixed-height tabbed panel that replaces the hero image when a row is
   selected in a datasheet. Contains Details form + child datasheets.
   ============================================================================= */

/* Container and layout */
.detail-panel {
  display: none;
  flex-direction: column;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 420px;
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  background: var(--color-surface);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.detail-panel.active {
  display: flex;
}

/* Tab navigation bar */
.detail-tabs {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
  flex-shrink: 0;
  overflow-x: auto;
}

.detail-tab-button {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-light);
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.detail-tab-button:hover {
  color: var(--color-text);
}

.detail-tab-button.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
}

/* Close button (top right) */
.detail-close-button {
  margin-left: auto;
  padding: 0.25rem 0.5rem;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--color-text-light);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: color 0.2s ease;
  flex-shrink: 0;
}

.detail-close-button:hover {
  color: var(--color-text);
}

/* Tab panels container — scrollable */
.detail-tab-panels {
  flex: 1;
  overflow: hidden;
  position: relative;
}

.detail-tab-panel {
  display: none;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  padding: 0.75rem;
  overflow-y: auto;
}

.detail-tab-panel.active {
  display: block;
}

/* Details form (in Details tab) */
.detail-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-width: 100%;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.form-group label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text);
}

.form-group input,
.form-group select,
.form-group textarea {
  padding: 0.5rem;
  border: 1px solid var(--color-input-border);
  border-radius: 0.25rem;
  background: var(--color-input-bg);
  color: var(--color-input-text);
  font-family: inherit;
  font-size: 0.875rem;
}

.form-group input::placeholder,
.form-group textarea::placeholder {
  color: var(--color-text-light);
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 2px rgba(15, 118, 110, 0.1);
}

.form-group textarea {
  resize: vertical;
  min-height: 4rem;
  font-family: inherit;
}

/* Action buttons: sticky footer bar */
.detail-panel-actions {
  display: flex;
  gap: 0.5rem;
  padding: 0.75rem;
  border-top: 1px solid var(--color-border);
  background: var(--color-surface);
  flex-shrink: 0;
}

.detail-panel-actions .btn-save,
.detail-panel-actions .btn-new,
.detail-panel-actions .btn-discard {
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 0.25rem;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.detail-panel-actions .btn-save {
  background: var(--color-button-primary-bg);
  color: var(--color-button-primary-text);
}

.detail-panel-actions .btn-save:hover {
  opacity: 0.9;
}

.detail-panel-actions .btn-new {
  background: var(--color-button-secondary-bg);
  color: var(--color-button-secondary-text);
}

.detail-panel-actions .btn-new:hover {
  opacity: 0.8;
}

.detail-panel-actions .btn-discard {
  background: var(--color-button-secondary-bg);
  color: var(--color-button-secondary-text);
}

.detail-panel-actions .btn-discard:hover {
  opacity: 0.8;
}

/* Child datasheets in tab panels */
.detail-tab-panel .datasheet-container {
  height: 100%;
}

/* Hero ↔ Panel transitions */
.crew-hero {
  transition: opacity 0.2s ease, visibility 0.2s ease;
}

.crew-hero.hidden {
  opacity: 0;
  visibility: hidden;
}

.detail-panel {
  transition: opacity 0.2s ease, visibility 0.2s ease;
  opacity: 0;
  visibility: hidden;
}

.detail-panel.active {
  opacity: 1;
  visibility: visible;
}

/* Make hero-detail-stack a positioning context for the absolute detail-panel */
.hero-detail-stack {
  position: relative;
}

{% extends "base.html" %}

{% block title %}{{ role_title }} — Curator{% endblock %}

{% block content %}
<section class="crew-section {{ role }}">

    <!-- Hero image and detail panel share the same spot; toggle visibility -->
    <div class="hero-detail-stack">
        {% with
            role=role,
            hero_image=role + ".png",
            title=role_title,
            show_back=true
        %}
            {% include "partials/_crew_header.html" %}
        {% endwith %}

        <div id="detail-panel-container">
            {% with entity='projects', record_id=0, record={}, project_types=project_types, project_statuses=project_statuses %}
                {% include "partials/_detail_panel.html" %}
            {% endwith %}
        </div>
    </div>

    <!-- Tab Navigation -->
    <div class="tabs">
        {% for tab in tabs %}
            <button
                class="tab-btn {% if loop.first %}active{% endif %}"
                data-tab="tab-{{ tab.id }}"
            >{{ tab.label }}</button>
        {% endfor %}
    </div>

    <!-- Tab Panels -->
    {% for tab in tabs %}
        <div id="tab-{{ tab.id }}" class="tab-panel {% if loop.first %}active{% endif %}">
            {% include "partials/" + tab.template %}
        </div>
    {% endfor %}

</section>

<!-- Embed lookups and data for Tabulator and identity panels -->
<script>
    window.projectRecords  = {{ records | tojson }};
    window.projectTypes    = {{ project_types | tojson }};
    window.projectStatuses = {{ project_statuses | tojson }};

    // Tab switching
    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.addEventListener('click', function () {
            document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
            document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
            document.getElementById(this.dataset.tab).classList.add('active');
            this.classList.add('active');
        });
    });
</script>
{% endblock %}

/**
 * detail-panel.js
 *
 * Handles detail panel interactions:
 * - Opening detail panel when ⋯ is clicked on a datasheet row
 * - Closing detail panel on × button or Escape
 * - Tab switching
 * - Form save/new/discard on button click or keyboard shortcut
 * - Enter key moves to next field (like Tab) instead of submitting form
 *
 * Usage: Include in base.html with <script type="module" src="/static/js/detail-panel.js"></script>
 */

export function initDetailPanel() {
  // Get references to key elements
  const heroImage = document.querySelector('.crew-hero');
  const detailPanelContainer = document.getElementById('detail-panel-container');

  // Tab switching
  document.addEventListener('click', (e) => {
    if (e.target.classList.contains('detail-tab-button')) {
      const panel = e.target.closest('.detail-panel');
      if (!panel) return;

      const targetTab = e.target.dataset.tab;

      // Deactivate all buttons and panels in this detail panel
      panel.querySelectorAll('.detail-tab-button').forEach(btn => {
        btn.classList.remove('active');
      });
      panel.querySelectorAll('.detail-tab-panel').forEach(p => {
        p.classList.remove('active');
      });

      // Activate the clicked tab
      e.target.classList.add('active');
      panel.querySelector(`[data-tab="${targetTab}"]`).classList.add('active');
    }

    // Close button
    if (e.target.classList.contains('detail-close-button')) {
      closeDetailPanel();
    }

    // New button (Alt+N)
    if (e.target.classList.contains('btn-new')) {
      handleNewRecord(e);
    }

    // Discard button (Alt+X / Escape)
    if (e.target.classList.contains('btn-discard')) {
      closeDetailPanel();
    }
  });

  // Escape key to close detail panel
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && detailPanelContainer?.querySelector('.detail-panel.active')) {
      closeDetailPanel();
    }

    // Alt+S to save
    if (e.altKey && e.key === 's') {
      e.preventDefault();
      const detailPanel = detailPanelContainer?.querySelector('.detail-panel.active');
      if (detailPanel) {
        const form = detailPanel.querySelector('form.detail-form');
        if (form) form.dispatchEvent(new Event('submit'));
      }
    }

    // Alt+N to new
    if (e.altKey && e.key === 'n') {
      e.preventDefault();
      const detailPanel = detailPanelContainer?.querySelector('.detail-panel.active');
      if (detailPanel) {
        handleNewRecord(e);
      }
    }

    // Alt+X to discard
    if (e.altKey && e.key === 'x') {
      e.preventDefault();
      closeDetailPanel();
    }
  });

  // Enter key in form inputs: move to next field instead of submitting
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      const form = e.target.closest('form.detail-form');
      if (!form) return;

      // Only handle Enter in input and textarea elements
      if (!['INPUT', 'TEXTAREA'].includes(e.target.tagName)) return;

      e.preventDefault();

      // Get all focusable form elements (inputs, selects, textareas)
      const focusableElements = Array.from(form.querySelectorAll(
        'input:not([type="hidden"]), select, textarea'
      ));

      const currentIndex = focusableElements.indexOf(e.target);
      if (currentIndex !== -1 && currentIndex < focusableElements.length - 1) {
        // Move to next element
        focusableElements[currentIndex + 1].focus();
      } else if (currentIndex === focusableElements.length - 1) {
        // If at last field, blur to deselect
        e.target.blur();
      }
    }
  });

  // Form save
  document.addEventListener('submit', async (e) => {
    if (!e.target.classList.contains('detail-form')) return;
    e.preventDefault();

    const form = e.target;
    const entity = form.dataset.entity;
    const recordId = form.dataset.id;

    const formData = new FormData(form);
    const data = Object.fromEntries(formData);

    const saveUrl = `/crew/${entity}/${recordId}/save`;

    try {
      const res = await fetch(saveUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });

      if (res.ok) {
        // Update successful — close panel
        console.log(`${entity} ${recordId} saved`);
        closeDetailPanel();
        // TODO: Refresh datasheet grid
      } else {
        const errorText = await res.text();
        console.error(`Save failed: ${errorText}`);
      }
    } catch (err) {
      console.error('Save error:', err);
    }
  });
}

/**
 * Handle "New" button: save current record and reset form for next entry.
 */
function handleNewRecord(e) {
  const detailPanel = e.target?.closest('.detail-panel') || document.querySelector('.detail-panel.active');
  if (!detailPanel) return;

  const form = detailPanel.querySelector('form.detail-form');
  if (!form) return;

  // Save current record first
  form.dispatchEvent(new Event('submit'));

  // Reset form and focus Name field
  form.reset();
  const nameField = form.querySelector('input[name="name"]');
  if (nameField) {
    nameField.focus();
  }
}

/**
 * Open detail panel for a specific row.
 *
 * Called when user clicks ⋯ on a datasheet row.
 * Fetches full record, renders panel, fades hero/panel, attaches listeners.
 */
export async function openDetailPanel(entity, recordId) {
  const heroImage = document.querySelector('.crew-hero');
  const detailPanelContainer = document.getElementById('detail-panel-container');

  // Fetch full record data
  let record;
  try {
    const res = await fetch(`/crew/${entity}/${recordId}`);
    if (!res.ok) throw new Error(`Fetch failed: ${res.status}`);
    record = await res.json();
  } catch (err) {
    console.error('Could not fetch record:', err);
    return;
  }

  // Render detail panel partial (deferred — will be rendered by template initially)
  // For now, just activate the panel if it exists

  const detailPanel = detailPanelContainer?.querySelector('.detail-panel');
  if (!detailPanel) {
    console.error('Detail panel not found in DOM');
    return;
  }

  // Update panel data attributes
  detailPanel.dataset.entity = entity;
  detailPanel.dataset.id = recordId;

  // Fade out hero, fade in detail panel
  if (heroImage) {
    heroImage.classList.add('hidden');
  }
  detailPanel.classList.add('active');

  // Reset form to first tab
  const firstButton = detailPanel.querySelector('.detail-tab-button');
  const firstPanel = detailPanel.querySelector('[data-tab="details"]');
  if (firstButton && firstPanel) {
    detailPanel.querySelectorAll('.detail-tab-button').forEach(b => b.classList.remove('active'));
    detailPanel.querySelectorAll('.detail-tab-panel').forEach(p => p.classList.remove('active'));
    firstButton.classList.add('active');
    firstPanel.classList.add('active');
  }

  // Focus Name field
  const nameField = detailPanel.querySelector('input[name="name"]');
  if (nameField) {
    nameField.focus();
  }
}

/**
 * Close the detail panel and fade hero back in.
 */
export function closeDetailPanel() {
  const heroImage = document.querySelector('.crew-hero');
  const detailPanelContainer = document.getElementById('detail-panel-container');
  const detailPanel = detailPanelContainer?.querySelector('.detail-panel');

  if (detailPanel) {
    detailPanel.classList.remove('active');
  }
  if (heroImage) {
    heroImage.classList.remove('hidden');
  }
}

// Initialize on page load
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initDetailPanel);
} else {
  initDetailPanel();
}

// Expose to global scope for HTML onclick handlers
window.openDetailPanel = openDetailPanel;
window.closeDetailPanel = closeDetailPanel;

