/* =============================================================================
   Detail Panel Component

   Tabbed panel that occupies the same spot as the hero image. Opening the
   panel hides the hero (display:none) and shows the panel (display:flex).
   Contains Details form + child datasheets.
   ============================================================================= */

/* Container and layout */
.detail-panel {
  display: none;            /* hidden by default */
  flex-direction: column;
  height: 420px;
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  background: var(--color-surface);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.detail-panel.active {
  display: flex;
}

/* Hero image hides when detail panel is active */
.crew-header.hidden {
  display: none;
}

/* Tab navigation bar */
.detail-tabs {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
  flex-shrink: 0;
  overflow-x: auto;
}

.detail-tab-button {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-light);
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.detail-tab-button:hover {
  color: var(--color-text);
}

.detail-tab-button.active {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
}

/* Action bar: Save/Discard centered, Close pinned right */
.detail-action-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0.4rem 0.5rem;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
  flex-shrink: 0;
  position: relative;
}

.detail-form-actions {
  display: flex;
  gap: 0.5rem;
}

/* Close button (pinned top-right of action bar) */
.detail-close-button {
  position: absolute;
  right: 0.5rem;
  padding: 0.25rem 0.5rem;
  font-size: 1.5rem;
  line-height: 1;
  color: var(--color-text-light);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: color 0.2s ease;
}

.detail-close-button:hover {
  color: var(--color-text);
}

/* Tab panels container */
.detail-tab-panels {
  flex: 1;
  overflow: hidden;
  position: relative;
}

.detail-tab-panel {
  display: none;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  padding: 0.75rem;
  overflow-y: auto;
}

.detail-tab-panel.active {
  display: block;
}

/* Details form (in Details tab) */
.detail-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-width: 100%;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.form-group label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text);
}

.form-group input,
.form-group select,
.form-group textarea {
  padding: 0.5rem;
  border: 1px solid var(--color-input-border);
  border-radius: 0.25rem;
  background: var(--color-input-bg);
  color: var(--color-input-text);
  font-family: inherit;
  font-size: 0.875rem;
}

.form-group input::placeholder,
.form-group textarea::placeholder {
  color: var(--color-text-light);
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 2px rgba(15, 118, 110, 0.1);
}

.form-group textarea {
  resize: vertical;
  min-height: 4rem;
  font-family: inherit;
}

/* Child datasheets in tab panels */
.detail-tab-panel .datasheet-container {
  height: 100%;
}

