   ============================================================================= */

/* ---------------------------------------------------------------------------
   Box model reset
   --------------------------------------------------------------------------- */

*, *::before, *::after {
  box-sizing: border-box;
}

/* ---------------------------------------------------------------------------
   CSS Variables — defaults, overridden by theme files
   --------------------------------------------------------------------------- */

:root {
  /* Colors */
  --color-primary:    #2c3e50;
  --color-accent:     #0f766e;   /* WCYJ teal */
  --color-bg:         #f5f7fa;
  --color-surface:    #ffffff;
  --color-border:     #dde1e7;
  --color-text:       #2c3e50;
  --color-text-light: #6b7280;

  /* Semantic status colors */
  --color-success: #27ae60;
