/**
 * detail-panel.js
 *
 * Handles detail panel interactions:
 * - Opening detail panel for existing records (⋯ button)
 * - Opening detail panel for new records (+ Add button)
 * - Closing panel on × / Alt+X / Escape
 * - Tab switching
 * - Save (Alt+S) — save and close
 * - New  (Alt+N) — save current, clear form, focus Name
 * - Discard (Alt+X) — discard and close
 *
 * Hero image and detail panel occupy the same spot. Opening the panel
 * hides the hero (display:none) and shows the panel (display:flex).
 */

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

function getPanel() {
  return document.querySelector('#detail-panel-container .detail-panel');
}

function getForm() {
  return document.getElementById('detail-form');
}

function getHero() {
  return document.querySelector('.crew-header');
}

function showPanel() {
  const panel = getPanel();
  const hero  = getHero();
  if (panel) panel.classList.add('active');
  if (hero)  hero.classList.add('hidden');
}

function hidePanel() {
  const panel = getPanel();
  const hero  = getHero();
  if (panel) panel.classList.remove('active');
  if (hero)  hero.classList.remove('hidden');
}

function resetToDetailsTab() {
  const panel = getPanel();
  if (!panel) return;
  panel.querySelectorAll('.detail-tab-button').forEach(b => b.classList.remove('active'));
  panel.querySelectorAll('.detail-tab-panel').forEach(p => p.classList.remove('active'));
  const firstBtn   = panel.querySelector('.detail-tab-button');
  const detailsTab = panel.querySelector('.detail-tab-panel[data-tab="details"]');
  if (firstBtn)   firstBtn.classList.add('active');
  if (detailsTab) detailsTab.classList.add('active');
}

function clearForm() {
  const form = getForm();
  if (!form) return;
  form.dataset.id = '';
  form.querySelectorAll('input, textarea').forEach(el => el.value = '');
  form.querySelectorAll('select').forEach(el => el.selectedIndex = 0);
}

function focusName() {
  const nameField = document.getElementById('detail-name');
  if (nameField) {
    nameField.focus();
    nameField.select();
  }
}

function populateForm(record) {
  const form = getForm();
  if (!form) return;
  form.dataset.id = record.id ?? '';

  const nameField   = form.querySelector('[name="name"]');
  const typeField   = form.querySelector('[name="type_id"]');
  const statusField = form.querySelector('[name="status_id"]');
  const descField   = form.querySelector('[name="description"]');

  if (nameField)   nameField.value   = record.name        ?? '';
  if (typeField)   typeField.value   = record.type_id     ?? '';
  if (statusField) statusField.value = record.status_id   ?? '';
  if (descField)   descField.value   = record.description ?? '';
}

// ---------------------------------------------------------------------------
// Save to server
// Returns the saved record on success, null on failure.
// ---------------------------------------------------------------------------

async function saveForm() {
  const form = getForm();
  if (!form) return null;

  const entity   = form.dataset.entity;
  const recordId = form.dataset.id;
  const isNew    = !recordId;

  const formData = new FormData(form);
  const data     = Object.fromEntries(formData);

  const url = isNew
    ? `/crew/${entity}/save`
    : `/crew/${entity}/${recordId}/save`;

  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
    });

    if (res.ok) {
      const saved = await res.json();
      // Update form id to the newly saved record's id
      form.dataset.id = saved.id;
      const panel = getPanel();
      if (panel) panel.dataset.id = saved.id;
      return saved;
    } else {
      const err = await res.json().catch(() => ({ detail: res.statusText }));
      alert(err.detail || 'Save failed');
      return null;
    }
  } catch (err) {
    console.error('Save error:', err);
    alert('Save error: ' + err.message);
    return null;
  }
}

// ---------------------------------------------------------------------------
// Button handlers
// ---------------------------------------------------------------------------

async function handleSave() {
  const saved = await saveForm();
  if (saved) hidePanel();
}

async function handleNew() {
  // Always save current form first (clean or dirty, new or existing)
  const saved = await saveForm();
  if (!saved) return; // save failed — don't clear the form

  // Clear and ready for next entry
  clearForm();
  resetToDetailsTab();
  focusName();
  // Refresh the grid so the just-saved record appears
  if (window._refreshProjectsGrid) window._refreshProjectsGrid();
}

function handleDiscard() {
  hidePanel();
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Open detail panel for an existing record.
 * Fetches record from server and populates the form.
 */
export async function openDetailPanel(entity, recordId) {
  let record;
  try {
    const res = await fetch(`/crew/${entity}/${recordId}`);
    if (!res.ok) throw new Error(`Fetch failed: ${res.status}`);
    record = await res.json();
  } catch (err) {
    console.error('Could not fetch record:', err);
    return;
  }

  const panel = getPanel();
  const form  = getForm();
  if (!panel || !form) return;

  panel.dataset.entity = entity;
  panel.dataset.id     = recordId;
  form.dataset.entity  = entity;

  populateForm(record);
  resetToDetailsTab();
  showPanel();
}

/**
 * Open detail panel in new-record mode.
 * Form is empty, save will POST to /crew/{entity}/save.
 */
export function openNewRecordPanel(entity) {
  const panel = getPanel();
  const form  = getForm();
  if (!panel || !form) return;

  panel.dataset.entity = entity;
  panel.dataset.id     = '';
  form.dataset.entity  = entity;

  clearForm();
  resetToDetailsTab();
  showPanel();
  focusName();
}

/**
 * Close the detail panel and restore the hero image.
 */
export function closeDetailPanel() {
  hidePanel();
}

// ---------------------------------------------------------------------------
// Init — wire up all event listeners
// ---------------------------------------------------------------------------

export function initDetailPanel() {
  // Tab switching
  document.addEventListener('click', (e) => {
    if (e.target.classList.contains('detail-tab-button')) {
      const panel = e.target.closest('.detail-panel');
      if (!panel) return;
      const targetTab = e.target.dataset.tab;
      panel.querySelectorAll('.detail-tab-button').forEach(b => b.classList.remove('active'));
      panel.querySelectorAll('.detail-tab-panel').forEach(p => p.classList.remove('active'));
      e.target.classList.add('active');
      const tabPanel = panel.querySelector(`.detail-tab-panel[data-tab="${targetTab}"]`);
      if (tabPanel) tabPanel.classList.add('active');
    }

    if (e.target.classList.contains('detail-close-button')) handleDiscard();
    if (e.target.classList.contains('btn-save'))            handleSave();
    if (e.target.classList.contains('btn-new'))             handleNew();
    if (e.target.classList.contains('btn-discard'))         handleDiscard();
  });

  // Keyboard shortcuts
  document.addEventListener('keydown', (e) => {
    const panel = getPanel();
    if (!panel?.classList.contains('active')) return;

    // Alt+S — Save and close
    if (e.altKey && e.key === 's') { e.preventDefault(); handleSave(); }
    // Alt+N — Save and new
    if (e.altKey && e.key === 'n') { e.preventDefault(); handleNew(); }
    // Alt+X or Escape — Discard and close
    if ((e.altKey && e.key === 'x') || e.key === 'Escape') { e.preventDefault(); handleDiscard(); }
  });
}

// ---------------------------------------------------------------------------
// Expose for non-module scripts (e.g. _projects_table.html)
// ---------------------------------------------------------------------------
window.openDetailPanel    = openDetailPanel;
window.openNewRecordPanel = openNewRecordPanel;
window.closeDetailPanel   = closeDetailPanel;

// Initialize
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initDetailPanel);
} else {
  initDetailPanel();
}

{#
  _datasheet.html

  Reusable Tabulator datasheet grid.

  This partial renders just the Tabulator instance. It is always used as
  a child of _datasheet_with_header.html (which provides the + button,
  search, and controls).

  Parameters:
    - container_id (str): DOM id for Tabulator to mount to (required)
    - entity (str): QueryLoader entity name (e.g., "tasks", "contact_emails")
    - query_name (str): QueryLoader query name (e.g., "for_project")
    - query_params (str): Comma-separated bind parameters (e.g., "123")
    - columns (list): Column definitions for Tabulator
    - save_url (str): POST endpoint for saving row edits
    - add_url (str, optional): POST endpoint for adding new rows

  Example usage (from _datasheet_with_header.html):

    {% include '_datasheet.html' with
        container_id='tasks-datasheet',
        entity='tasks',
        query_name='for_project',
        query_params=record.id,
        columns=[
          { "title": "Name", "field": "name", "width": 200, "editor": "input" },
          { "title": "Status", "field": "status_id", "width": 100 }
        ],
        save_url='/crew/tasks/save'
    %}
#}

<div id="{{ container_id }}" style="height: 100%;"></div>

<script>
window.addEventListener('load', function () {

  const container = document.getElementById('{{ container_id }}');
  const entity = '{{ entity }}';
  const queryName = '{{ query_name }}';
  const queryParams = '{{ query_params }}';
  const ajaxUrl = `/api/query/${entity}/${queryName}?params=${queryParams}`;

  const columns = {{ columns | tojson }};

  // -------------------------------------------------------------------------
  // Save a row to the server via generic entity endpoint
  // -------------------------------------------------------------------------
  async function saveRow(row) {
    const data = row.getData();
    const isNew = !data.id;

    // Don't save a new row with no content — just delete it
    const firstEditable = columns.find(c => c.editor);
    if (isNew && firstEditable && !data[firstEditable.field]) {
      row.delete();
      return true;
    }

    const url = isNew
      ? `/api/${entity}/save`
      : `/api/${entity}/${data.id}/save`;

    // Only send editable columns
    const editableFields = columns
      .filter(c => c.editor && c.field !== 'id')
      .map(c => c.field);

    const payload = {};
    editableFields.forEach(f => { payload[f] = data[f] ?? null; });

    // For new rows, also include the parent foreign key if present
    // (e.g. contact_id, project_id — passed in via query_params)
    {% if query_params %}
    if (isNew) {
      const paramKey = '{{ entity }}'.replace(/s$/, '_id').replace('contact_email', 'contact').replace('contact_phone', 'contact');
      if (paramKey && !payload[paramKey]) {
        payload[paramKey] = {{ query_params }};
      }
    }
    {% endif %}

    const resp = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });

    if (!resp.ok) {
      const err = await resp.json().catch(() => ({ detail: resp.statusText }));
      alert(err.detail || 'Save failed');
      return false;
    }

    const saved = await resp.json();
    row.update(saved);
    return true;
  }

  // -------------------------------------------------------------------------
  // Delete a row from the server
  // -------------------------------------------------------------------------
  async function deleteRow(row) {
    const id = row.getData().id;
    if (!id) { row.delete(); return; }

    if (!confirm('Delete this row?')) return;

    const resp = await fetch(`/api/${entity}/${id}`, { method: 'DELETE' });
    if (resp.ok) {
      row.delete();
    } else {
      alert('Delete failed');
    }
  }

  // -------------------------------------------------------------------------
  // Tabulator init — uses global Tabulator loaded by base.html via CDN
  // -------------------------------------------------------------------------
  const table = new Tabulator(container, {
    height: '100%',
    layout: 'fitColumns',
    ajaxURL: ajaxUrl,
    ajaxConfig: { headers: { 'Accept': 'application/json' } },
    ajaxResponse: (url, params, response) => response.records || [],
    editTriggerEvent: 'dblclick',
    columns: columns,

    // Auto-save when a cell edit is confirmed (Enter or click away)
    cellEdited: async function(cell) {
      await saveRow(cell.getRow());
    },

    rowContextMenu: [
      {
        label: 'Delete row',
        action: (e, row) => deleteRow(row),
      }
    ],

    dataLoadError: (error) => {
      console.error(`Failed to load ${entity}/${queryName}:`, error);
    },
  });

  // Esc — delete empty new row, or cancel
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      // Find any unsaved new row and remove it
      const newRow = table.getRows().find(r => !r.getData().id);
      if (newRow) {
        newRow.delete();
      }
    }
  });

  // Store reference on window for parent access (e.g. refresh after external save)
  window[`tabulator_${container.id}`] = table;
  window[`refresh_${container.id}`] = () => table.setData(ajaxUrl);

});
</script>

