/* =============================================================================
   Dark Theme
   Overrides light.css variables for dark mode readability
   ============================================================================= */

:root {
    /* App shell — dark backgrounds, light text */
    --color-primary:      #0f766e;  /* teal stays same for accent */
    --color-primary-dark: #0d6460;
    --color-primary-light:#20b2aa;  /* Lighter teal for dark theme contrast */

    /* Neutrals — inverted */
    --color-bg:           #1a1a1a;
    --color-surface:      #2a2a2a;
    --color-border:       #404040;
    --color-text:         #e5e5e5;
    --color-text-light:   #a0a0a0;

    /* Semantic */
    --color-danger:       #dc2626;
    --color-danger-bg:    #3a1a1a;
    --color-success:      #166534;
    --color-warning:      #b45309;
}

body {
    background: var(--color-bg);
    color: var(--color-text);
}

/* -- Navbar ---------------------------------------------------------------- */

.navbar {
    background: var(--color-surface);
    border-bottom: 2px solid var(--color-primary);
}

.nav-brand a {
    color: var(--color-primary);
}

.nav-links a {
    color: var(--color-text-light);
}

.nav-links a:hover {
    color: var(--color-primary);
}

/* -- Footer ---------------------------------------------------------------- */

footer {
    color: var(--color-text-light);
    border-top-color: var(--color-border);
}

/* -- Links ----------------------------------------------------------------- */

a {
    color: var(--color-primary);
}

a:hover {
    color: var(--color-primary-light);
}

/* -- Landing page specific ------------------------------------------------- */

h1, h2, h3, h4, h5, h6 {
    color: var(--color-text);
}

.subtitle {
    color: var(--color-text-light);
}

/* =============================================================================
   Tab Navigation — Main tabs
   ============================================================================= */

.tab-bar {
    display: flex;
    gap: 0.5rem;
    border-bottom: 2px solid var(--color-border);
    margin: 1.5rem 0 1.5rem 0;
    padding: 0;
}

.tab-btn {
    padding: 0.75rem 1.5rem;
    border: none;
    background: transparent;
    cursor: pointer;
    border-bottom: 2px solid transparent;
    color: var(--color-text-light);
    font-size: 1rem;
    font-weight: 500;
    transition: all 0.2s ease;
}

.tab-btn:hover {
    color: var(--color-primary);
}

.tab-btn.active {
    border-bottom-color: var(--color-primary);
    color: var(--color-primary);
    font-weight: 600;
}

/* =============================================================================
   Tab Panels
   ============================================================================= */

.tab-panels {
    display: block;
}

.tab-panel {
    display: none;
}

.tab-panel.active {
    display: block;
    animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

/* =============================================================================
   Sub-tab Navigation — Within Identities tab
   ============================================================================= */

.sub-tab-bar {
    display: flex;
    gap: 0.5rem;
    border-bottom: 1px solid var(--color-border);
    margin: 1.5rem 0 1.5rem 0;
    padding: 0;
}

.sub-tab-btn {
    padding: 0.5rem 1rem;
    border: none;
    background: transparent;
    cursor: pointer;
    border-bottom: 2px solid transparent;
    color: var(--color-text-light);
    font-size: 0.9rem;
    font-weight: 500;
    transition: all 0.2s ease;
}

.sub-tab-btn:hover {
    color: var(--color-primary);
}

.sub-tab-btn.active {
    border-bottom-color: var(--color-primary);
    color: var(--color-primary);
    font-weight: 600;
}

/* =============================================================================
   Sub-tab Panels
   ============================================================================= */

.sub-tab-panels {
    display: block;
}

.sub-tab-panel {
    display: none;
}

.sub-tab-panel.active {
    display: block;
    animation: fadeIn 0.2s ease;
}

/* =============================================================================
   Placeholder Styling
   ============================================================================= */

.sub-form-placeholder {
    padding: 2rem;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 0.5rem;
    text-align: center;
    margin-top: 1.5rem;
}

.sub-form-placeholder p {
    margin: 0.5rem 0;
    color: var(--color-text);
}

.sub-form-placeholder .hint {
    font-size: 0.9rem;
    color: var(--color-text-light);
}

/* =============================================================================
   Responsive
   ============================================================================= */

@media (max-width: 640px) {
    .tab-bar,
    .sub-tab-bar {
        gap: 0.25rem;
    }

    .tab-btn,
    .sub-tab-btn {
        padding-left: 1rem;
        padding-right: 1rem;
        font-size: 0.9rem;
    }
}

