    {# ---- Subprojects ---- #}
    {% if subprojects %}
    <div class="panel-subprojects">
      <div class="panel-section-label">Subprojects</div>
      {% for sp in subprojects %}
      <div class="subform-row">
        <span class="subform-row-name">
          <a href="#" onclick="loadPanel('{{ sp.slug }}'); return false;">{{ sp.name }}</a>
        </span>
        <span class="subform-row-meta">{{ sp.status }}</span>
      </div>
      {% endfor %}
    </div>
    {% endif %}

  </div>{# end panel-card #}

  {# ---- Task search ---- #}
  <div class="panel-search-row">
    <input type="search"
           id="task-search"
           placeholder="Search tasks…"
           oninput="filterTasks(this.value)"
           class="panel-search-input">
  </div>

  {# ---- Tasks card ---- #}
  <div class="panel-card">
    <div class="subform-header">
      <span>Tasks <span class="subform-footnote-marker">*</span></span>
      <button type="button" class="btn-secondary btn-sm" onclick="openAddTaskDialog()">+ Add</button>
    </div>
    <div class="subform-footnote">* double-click a task to change status or priority</div>
    <div class="subform-body" id="task-subform">
      {% if tasks %}
        {% for task in tasks %}
        <div class="subform-row task-depth-{{ task.depth }}"
             data-task-id="{{ task.id }}"
             data-task-desc="{{ task.description | e }}"
             data-task-status="{{ task.status }}"
             data-task-priority="{{ task.priority }}"
             data-task-links="{{ task.links or '' }}"
             data-task-notes="{{ task.notes or '' | e }}"
