            {{ task.status }}
          </span>
          <span class="subform-row-name {% if task.is_terminal %}task-done{% endif %}">
            {{ task.description }}
          </span>
          <span class="subform-row-meta task-pri-{{ task.priority }}">{{ task.priority }}</span>
          <a href="/tasks/{{ task.id }}/edit?next_url=/projects/board" class="subform-row-edit" title="Full edit">✎</a>
        </div>
        {% endfor %}
      {% else %}
        <div class="subform-empty">No tasks yet.</div>
      {% endif %}
    </div>
  </div>

  {# ---- Files card ---- #}
  <div class="panel-card">
    <div class="subform-header">
      <span>Files</span>
      <a href="/files/new?project_id={{ project.id }}&next_url=/projects/board" class="btn-secondary btn-sm">+ Add</a>
    </div>
    <div class="subform-body">
      {% if files %}
        {% for f in files %}
        <div class="subform-row">
          <span class="subform-row-name">
            <a href="{{ f.location }}" target="_blank" rel="noopener">{{ f.label }}</a>
          </span>
          <span class="subform-row-meta">{{ f.location_type }}</span>
          <a href="/files/{{ f.id }}/edit?next_url=/projects/board" class="subform-row-edit">✎</a>
        </div>
        {% endfor %}
      {% else %}
        <div class="subform-empty">No files attached.</div>
      {% endif %}
    </div>
  </div>

</div>

{# ---- Add task dialog ---- #}
<div id="add-task-dialog-backdrop" class="task-dialog-backdrop" style="display:none;" onclick="closeAddTaskDialog()">
  <div class="task-dialog" onclick="event.stopPropagation()">
    <div class="task-dialog-title">New Task — {{ project.name }}</div>
    <form hx-post="/tasks/new-panel/{{ project.slug }}"
