{# ---- Task edit dialog ---- #}
<div id="task-dialog-backdrop" class="task-dialog-backdrop" style="display:none;" onclick="closeTaskDialog()">
  <div class="task-dialog" onclick="event.stopPropagation()">
    <div class="task-dialog-title" id="task-dialog-desc"></div>
    <form id="task-dialog-form"
