      <input type="hidden" name="description" id="task-dialog-hidden-desc">
      <input type="hidden" name="sort_order" value="0">
      <input type="hidden" name="is_terminal" id="task-dialog-terminal">

      <div class="task-dialog-field">
        <label>Status</label>
        <select name="status_id" id="task-dialog-status" onchange="updateTerminal(this)">
          {% for s in status_task_options %}
            <option value="{{ s.id }}" data-terminal="{{ 'true' if s.is_terminal else 'false' }}">{{ s.name }}</option>
          {% endfor %}
