<script>
function panelEdit(displayEl) {
    var input = displayEl.nextElementSibling;
    displayEl.style.display = 'none';
    input.style.display = '';
    input.focus();
    document.getElementById('panel-save-bar').style.display = 'flex';

    input.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') { panelCancelOne(displayEl, input); }
    }, { once: true });
}

function panelCancelOne(displayEl, inputEl) {
    inputEl.style.display = 'none';
    displayEl.style.display = '';
}

function panelCancelAll() {
    document.querySelectorAll('.panel-field-input').forEach(function(input) {
        var display = input.previousElementSibling;
        input.style.display = 'none';
        if (display) display.style.display = '';
    });
    document.getElementById('panel-save-bar').style.display = 'none';
}

function loadPanel(slug) {
    htmx.ajax('GET', '/projects/' + slug + '/panel', {target: '#board-detail', swap: 'innerHTML'});
    document.querySelectorAll('.board-list-item').forEach(function(i) {
        i.classList.remove('board-list-item--active');
        if (i.getAttribute('hx-get') === '/projects/' + slug + '/panel') {
            i.classList.add('board-list-item--active');
        }
    });
}

function openTaskDialog(row) {
    var taskId = row.dataset.taskId;
    var description = row.dataset.taskDesc;
    var statusName = row.dataset.taskStatus;
    var priority = row.dataset.taskPriority;
    var links = row.dataset.taskLinks || '';
    var notes = row.dataset.taskNotes || '';

    document.getElementById('task-dialog-desc').textContent = description;
    document.getElementById('task-dialog-hidden-desc').value = description;
    document.getElementById('task-dialog-links').value = links;
    document.getElementById('task-dialog-notes').value = notes;
    document.getElementById('task-dialog-form').setAttribute('hx-post', '/tasks/' + taskId + '/edit-panel');
    htmx.process(document.getElementById('task-dialog-form'));

    var statusSelect = document.getElementById('task-dialog-status');
    for (var i = 0; i < statusSelect.options.length; i++) {
        if (statusSelect.options[i].text === statusName) {
            statusSelect.selectedIndex = i;
            break;
        }
    }

    var prioritySelect = document.getElementById('task-dialog-priority');
    for (var i = 0; i < prioritySelect.options.length; i++) {
        if (prioritySelect.options[i].text === priority) {
            prioritySelect.selectedIndex = i;
            break;
        }
    }

    updateTerminal(statusSelect);
    document.getElementById('task-dialog-backdrop').style.display = 'flex';
}

function closeTaskDialog() {
    document.getElementById('task-dialog-backdrop').style.display = 'none';
}

function updateTerminal(select) {
    var selected = select.options[select.selectedIndex];
    document.getElementById('task-dialog-terminal').value =
        selected.dataset.terminal === 'true' ? 'true' : 'false';
}

function filterTasks(query) {
    var rows = document.querySelectorAll('#task-subform .subform-row');
    var q = query.toLowerCase().trim();
    rows.forEach(function(row) {
        var desc = row.dataset.taskDesc ? row.dataset.taskDesc.toLowerCase() : '';
        var status = row.dataset.taskStatus ? row.dataset.taskStatus.toLowerCase() : '';
        var priority = row.dataset.taskPriority ? row.dataset.taskPriority.toLowerCase() : '';
        row.style.display = (q === '' || desc.includes(q) || status.includes(q) || priority.includes(q)) ? '' : 'none';
    });
}

document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
        closeTaskDialog();
        closeAddTaskDialog();
    }
});

function openAddTaskDialog() {
    document.getElementById('add-task-dialog-backdrop').style.display = 'flex';
}

function closeAddTaskDialog() {
    document.getElementById('add-task-dialog-backdrop').style.display = 'none';
}
</script>

{% extends "base.html" %}
{% block title %}{% if task %}Edit Task{% else %}New Task{% endif %} — The Curator{% endblock %}

{% block content %}
<div class="page-header">
    <h1>{% if task %}Edit Task{% else %}New Task{% endif %}</h1>
    <a href="{{ next }}" class="btn-secondary">Cancel</a>
</div>

<form method="post"
      action="{% if task %}/tasks/{{ task.id }}/edit{% else %}/tasks/new/{{ project.slug }}{% endif %}"
      class="curator-form">

    <input type="hidden" name="project_slug" value="{{ project.slug }}">
    <input type="hidden" name="next_url" value="{{ next }}">

    {% for field in view.fields %}

    {% if field.name == "description" %}
    <label for="description">
        {{ field.label }}{% if field.required %} *{% endif %}
        <textarea id="description"
                  name="description"
                  {% if field.required %}required{% endif %}
                  placeholder="{{ field.placeholder or '' }}">{{ task.description if task else '' }}</textarea>
    </label>

    {% elif field.name == "status_id" %}
    <label for="status_id">
        {{ field.label }}{% if field.required %} *{% endif %}
        <select id="status_id" name="status_id" {% if field.required %}required{% endif %}>
            <option value="">— select —</option>
            {% for opt in status_options %}
            <option value="{{ opt.id }}"
                {% if task and task.status_id == opt.id %}selected{% endif %}>
                {{ opt.display }} {{ opt.name }}
            </option>
            {% endfor %}
        </select>
    </label>

    {% elif field.name == "priority_id" %}
    <label for="priority_id">
        {{ field.label }}{% if field.required %} *{% endif %}
        <select id="priority_id" name="priority_id" {% if field.required %}required{% endif %}>
            <option value="">— select —</option>
            {% for opt in priority_options %}
            <option value="{{ opt.id }}"
                {% if task and task.priority_id == opt.id %}selected{% endif %}>
                {{ opt.name }}
            </option>
            {% endfor %}
        </select>
    </label>

    {% elif field.name == "parent_id" %}
    <label for="parent_id">
        {{ field.label }}
        <select id="parent_id" name="parent_id">
            <option value="">— none —</option>
            {% for opt in parent_options %}
            <option value="{{ opt.id }}"
                {% if task and task.parent_id == opt.id %}selected
                {% elif parent_id and parent_id == opt.id %}selected{% endif %}>
                {{ opt.description }}
            </option>
            {% endfor %}
        </select>
    </label>

    {% elif field.name == "links" %}
    <label for="links">
        {{ field.label }}
        <input type="text"
               id="links"
               name="links"
               value="{{ task.links if task else '' }}"
               placeholder="{{ field.placeholder or '' }}">
        {% if field.help_text %}
        <small class="field-help">{{ field.help_text }}</small>
        {% endif %}
    </label>

    {% elif field.name == "notes" %}
    <label for="notes">
        {{ field.label }}
        <textarea id="notes"
                  name="notes"
                  placeholder="{{ field.placeholder or '' }}">{{ task.notes if task else '' }}</textarea>
        {% if field.help_text %}
        <small class="field-help">{{ field.help_text }}</small>
        {% endif %}
    </label>

    {% endif %}
    {% endfor %}

    <div class="form-actions">
        <button type="submit" class="btn-primary">
            {% if task %}Save Changes{% else %}Create Task{% endif %}
        </button>
        <a href="{{ next }}" class="btn-secondary">Cancel</a>
    </div>

</form>

{# Force delete confirmation — only shown when task has children #}
{% if task and task.child_count and task.child_count > 0 %}
<div class="confirm-delete" style="margin-top: 2rem;">
    <p><strong>This task has {{ task.child_count }} subtask(s).</strong>
    Deleting it will also delete all subtasks.</p>
    <form method="post" action="/tasks/{{ task.id }}/force-delete">
        <input type="hidden" name="project_slug" value="{{ project.slug }}">
        <input type="hidden" name="next_url" value="{{ next }}">
        <button type="submit" class="btn-danger">Delete Task and All Subtasks</button>
    </form>
</div>
{% endif %}

{% endblock %}

