{#
  projects/_panel.html
  HTMX partial — loaded into #board-detail on project double-click.
  Inline editing: click a field value to edit, Save/Cancel to commit.
  Task editing: double-click a task row to open status/priority dialog.
#}

<div class="panel-wrap">

  {# ---- Header ---- #}
  <div class="panel-header">
    <div>
      <div class="panel-title" id="panel-title">{{ project.name }}</div>
      <div class="panel-meta">{{ project.status }} · {{ project.project_type or '—' }}</div>
    </div>
    <div class="panel-header-actions">
      <a href="/projects/{{ project.slug }}/edit" class="btn-secondary btn-sm">Full edit</a>
      <form method="post" action="/projects/{{ project.slug }}/delete"
            onsubmit="return confirm('Delete {{ project.name }}? This cannot be undone.');"
            style="display:inline;">
        <button type="submit" class="btn-danger btn-sm">Delete</button>
      </form>
    </div>
  </div>

  {# ---- Project details card ---- #}
  <div class="panel-card">

    <form method="post" action="/projects/{{ project.slug }}/edit" id="panel-edit-form">

      <div class="panel-field">
        <label>Description</label>
        <div class="panel-field-display" onclick="panelEdit(this)">
          {{ project.description or '—' }}
        </div>
        <textarea name="description" class="panel-field-input" style="display:none;" rows="3">{{ project.description or '' }}</textarea>
      </div>

      <div class="panel-fields-row">
        <div class="panel-field">
          <label>Status</label>
          <div class="panel-field-display" onclick="panelEdit(this)">{{ project.status }}</div>
          <select name="status_id" class="panel-field-input" style="display:none;">
            {% for s in status_options %}
              <option value="{{ s.id }}" {% if s.name == project.status %}selected{% endif %}>{{ s.name }}</option>
            {% endfor %}
          </select>
        </div>

        <div class="panel-field">
          <label>Type</label>
          <div class="panel-field-display" onclick="panelEdit(this)">{{ project.project_type or '—' }}</div>
          <select name="type_id" class="panel-field-input" style="display:none;">
            <option value="">—</option>
            {% for t in type_options %}
              <option value="{{ t.id }}" {% if t.name == project.project_type %}selected{% endif %}>{{ t.name }}</option>
            {% endfor %}
          </select>
        </div>

        <div class="panel-field">
          <label>Parent</label>
          <div class="panel-field-display" onclick="panelEdit(this)">{{ project.parent_name or '—' }}</div>
          <select name="parent_id" class="panel-field-input" style="display:none;">
            <option value="">—</option>
